package io.knowledgebrain.space;
import java.util.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import jakarta.servlet.http.HttpServletRequest;
import org.springframework.web.bind.annotation.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;
@RestController @ConditionalOnProperty(name="brain.space.group-review-authorization.enabled",havingValue="true")
final class GroupReviewAuthorizationController {
 private final GroupSpaceStore store;private final IdentityPrincipalClient identity;private final byte[] key;
 GroupReviewAuthorizationController(GroupSpaceStore store,IdentityPrincipalClient identity,@Value("${brain.space.group-review-authorization.key}")String key){if(!key.matches("[A-Za-z0-9_-]{43}"))throw new IllegalArgumentException("Dedicated credential required");this.store=store;this.identity=identity;this.key=("Bearer "+key).getBytes(StandardCharsets.US_ASCII);}
 @PostMapping("/internal/space/group-review-authorization") ResponseEntity<GroupSpaceStore.ReviewAccess> check(HttpServletRequest r)throws java.io.IOException{
  var h=Collections.list(r.getHeaders("Authorization"));if(!r.isSecure()||h.size()!=1||!MessageDigest.isEqual(key,h.getFirst().getBytes(StandardCharsets.US_ASCII))||r.getHeader("Cookie")!=null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);
  if(r.getQueryString()!=null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST);if(!"application/json".equalsIgnoreCase(Optional.ofNullable(r.getContentType()).orElse("").split(";",2)[0].strip()))throw new ResponseStatusException(HttpStatus.UNSUPPORTED_MEDIA_TYPE);var bytes=r.getInputStream().readNBytes(1025);if(bytes.length>1024)throw new ResponseStatusException(HttpStatus.PAYLOAD_TOO_LARGE);
  try{var j=tools.jackson.databind.json.JsonMapper.builder().enable(tools.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS).enable(tools.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).build().readTree(bytes);if(j==null||!j.isObject()||j.size()!=2||!j.path("token").isString()||!j.path("token").asString().matches("[A-Za-z0-9_-]{43}")||!j.path("groupId").isString()||!j.path("groupId").asString().matches("[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);var p=identity.resolve(j.path("token").asString(),r.getHeader("traceparent"));if(!"REGISTERED".equals(p.kind()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(store.reviewAccess(UUID.fromString(j.path("groupId").asString()),p.principalId()));}catch(tools.jackson.core.JacksonException ex){throw new ResponseStatusException(HttpStatus.BAD_REQUEST);}
 }
}
